import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.A5mep7Fe.js";const u=JSON.parse('{"title":"⚡ 06 · 解码策略与推理优化","description":"","frontmatter":{},"headers":[],"relativePath":"01-算法岗-AIGC与LLM/06-解码与推理优化.md","filePath":"01-算法岗-AIGC与LLM/06-解码与推理优化.md","lastUpdated":1786806808000}'),d={name:"01-算法岗-AIGC与LLM/06-解码与推理优化.md"};function n(i,t,l,s,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="⚡-06-·-解码策略与推理优化" tabindex="-1">⚡ 06 · 解码策略与推理优化 <a class="header-anchor" href="#⚡-06-·-解码策略与推理优化" aria-label="Permalink to &quot;⚡ 06 · 解码策略与推理优化&quot;">​</a></h1><blockquote><p>训练决定「模型能力上限」，推理优化决定「能不能用、用不用得起」。工程岗必看，算法岗常问。</p></blockquote><hr><h2 id="一、解码策略-decoding" tabindex="-1">一、解码策略（Decoding） <a class="header-anchor" href="#一、解码策略-decoding" aria-label="Permalink to &quot;一、解码策略（Decoding）&quot;">​</a></h2><p>逐 token 生成，每一步从概率分布采样：</p><table tabindex="0"><thead><tr><th>策略</th><th>做法</th><th>特点</th><th>适用</th></tr></thead><tbody><tr><td>贪心（Greedy）</td><td>每步取 argmax</td><td>确定、但易重复/平庸</td><td>简单任务</td></tr><tr><td>温度采样（Temperature）</td><td>缩放 logits 后 softmax 再采样</td><td>T 高更随机，T 低更集中</td><td>创意生成</td></tr><tr><td>Top-k</td><td>只在概率最高 k 个中采样</td><td>控制多样性</td><td>折中</td></tr><tr><td>Top-p（核采样）</td><td>取累计概率达 p 的最小集合</td><td>动态截断，更自然</td><td>对话首选</td></tr><tr><td>束搜索（Beam Search）</td><td>保留 top-b 条路径</td><td>适合有标准答案（翻译/代码）</td><td>确定性任务</td></tr></tbody></table><p><strong>本质</strong>：贪心/beam 偏「准」，采样偏「活」。对话用 top-p+temperature，代码/数学可 beam。</p><hr><h2 id="二、kv-cache-⭐-必考" tabindex="-1">二、KV Cache（⭐ 必考） <a class="header-anchor" href="#二、kv-cache-⭐-必考" aria-label="Permalink to &quot;二、KV Cache（⭐ 必考）&quot;">​</a></h2><p>自回归每生成一个 token，都要用到前面所有 token 的 K,V。若每次重算，复杂度爆炸。</p><p><strong>KV Cache</strong>：缓存已算过的 K,V，新 token 只需算自己的 Q 与缓存做注意力。</p><ul><li>显存占用：$2 \\times n \\times h \\times d_h \\times \\text{layers} \\times \\text{prec}$ （n=序列长，随长度线性增长）</li><li>这是<strong>长上下文显存瓶颈</strong>的根源 → 引出 KV 量化、PagedAttention、MQA/GQA。</li></ul><hr><h2 id="三、注意力变体-省-kv" tabindex="-1">三、注意力变体（省 KV） <a class="header-anchor" href="#三、注意力变体-省-kv" aria-label="Permalink to &quot;三、注意力变体（省 KV）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变体</th><th>做法</th><th>收益</th></tr></thead><tbody><tr><td>MQA（Multi-Query）</td><td>所有头共享一组 K,V</td><td>KV 显存大降，速度↑</td></tr><tr><td>GQA（Grouped-Query）</td><td>头分组共享 K,V</td><td>MQA 与 MHA 折中，质量/速度平衡（LLaMA2+ 采用）</td></tr></tbody></table><hr><h2 id="四、量化-quantization" tabindex="-1">四、量化（Quantization） <a class="header-anchor" href="#四、量化-quantization" aria-label="Permalink to &quot;四、量化（Quantization）&quot;">​</a></h2><p>降低权重/激活精度以减少显存与提速：</p><ul><li><strong>训练后量化 PTQ</strong>：W8A8、W4A16（GPTQ/AWQ）、NF4（QLoRA）</li><li><strong>AWQ</strong>：保护「重要权重」的 1% 通道，量化其余，精度损失小</li><li><strong>GPTQ</strong>：基于二阶信息逐层量化</li></ul><p>权衡：精度↓ vs 显存↓/速度↑。W4 通常可接受，W2 易崩。</p><hr><h2 id="五、投机解码-speculative-decoding" tabindex="-1">五、投机解码（Speculative Decoding） <a class="header-anchor" href="#五、投机解码-speculative-decoding" aria-label="Permalink to &quot;五、投机解码（Speculative Decoding）&quot;">​</a></h2><p>用<strong>小模型先草拟</strong>若干 token，大模型<strong>一次并行验证</strong>。若草稿命中率高，推理加速 2-3×，且<strong>输出分布与大模型一致</strong>（无损）。</p><hr><h2 id="六、其他加速" tabindex="-1">六、其他加速 <a class="header-anchor" href="#六、其他加速" aria-label="Permalink to &quot;六、其他加速&quot;">​</a></h2><ul><li><strong>FlashAttention</strong>：IO 感知的重计算，减少 HBM 读写，省显存且更快。</li><li><strong>PagedAttention（vLLM）</strong>：像操作系统页表一样管理 KV，减少碎片，提升吞吐。</li><li><strong>连续批处理（Continuous Batching）</strong>：动态拼不同请求，提升 GPU 利用率。</li><li><strong>蒸馏（Distillation）</strong>：大模型教小模型，得到高性价比小模型（如 DistilBERT、小杯 Qwen）。</li></ul><hr><h2 id="七、高频追问" tabindex="-1">七、高频追问 <a class="header-anchor" href="#七、高频追问" aria-label="Permalink to &quot;七、高频追问&quot;">​</a></h2><p><strong>Q1：为什么推理显存主要被 KV Cache 占？</strong></p><blockquote><p>权重只需一份；KV 随序列长度线性增长，长对话/长文档下 KV 可超权重。多请求并发时更显著。</p></blockquote><p><strong>Q2：GQA 相比 MQA 好在哪？</strong></p><blockquote><p>MQA 共享过头会损质量；GQA 分组共享，在显存节省与质量间取得更好平衡，成为主流默认。</p></blockquote><p><strong>Q3：量化会损失精度，为什么还能用？</strong></p><blockquote><p>大模型有冗余，且权重分布集中；AWQ/GPTQ 针对性保护重要通道，W4 下任务精度损失常 &lt;1%。</p></blockquote><hr><p>➡️ 下一步：<a href="./07-长上下文与MoE">07-长上下文与MoE</a></p>',36)])])}const g=e(d,[["render",n]]);export{u as __pageData,g as default};
